INSERT INTO _nft_depth_wave_b_0096 (slug, canonical_profile) VALUES ('cryptopunks', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:cryptopunks","type":"nft_collection","slug":"cryptopunks","name":"CryptoPunks","aliases":[]},"classification":{"subtype":"historical generative profile-picture collection","tags":["ethereum","historical","pfp","nonprofit_stewardship","native_marketplace"],"chains":["Ethereum"],"jurisdictions":["United States"]},"status":{"operating_state":"operating_nonprofit_stewardship","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:status"]},"outcome":{"label":"successful_cultural_infrastructure","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:cryptopunks:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"CryptoPunks is a fixed set of 10,000 algorithmically generated 24-by-24 pixel characters released free on Ethereum in 2017 by Larva Labs founders Matt Hall and John Watkinson. The collection predates ERC-721 and uses its own original market contract, with wrappers available for newer marketplaces. Infinite Node Foundation now owns and stewards the IP. A Punk grants control of the token and licensed uses of its art; it is not equity in NODE, a museum share or a promise of income.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:what_it_is:1","claim:cryptopunks:section:what_it_is:2","claim:cryptopunks:section:what_it_is:3"]},"what_happened":{"body":"The project began as a free claim and gradually became a reference point for profile-picture NFTs and onchain art. Yuga Labs acquired the IP in 2022 and expanded holder commercial rights. In May 2025, Yuga transferred the full collection IP to the nonprofit NODE Foundation, with the original creators joining its advisory structure. NODE then opened a permanent Palo Alto hub with the full 10,000-piece exhibition and continued the native marketplace. The collection changed stewards twice without expanding supply or issuing a Punk token.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:what_happened:1","claim:cryptopunks:section:what_happened:2","claim:cryptopunks:section:what_happened:3"]},"why_this_outcome":{"body":"CryptoPunks endured because it combined early Ethereum provenance, a fixed and instantly legible cohort, an original onchain marketplace and a community that could keep using the work after its creators stepped back. Later stewards added licensing and institutional presentation without asking holders to migrate into a new collection or token. That reduced roadmap failure risk and kept the historical object stable. These factors plausibly explain cultural durability; they do not prove that any one choice caused prices or liquidity to hold.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:why_this_outcome:1","claim:cryptopunks:section:why_this_outcome:2","claim:cryptopunks:section:why_this_outcome:3"]},"strategic_choices":{"body":"Larva Labs chose a free distribution, fixed supply and self-contained market rather than a large primary sale or continuous content roadmap. Yuga later clarified commercial-use rights, while NODE chose nonprofit preservation, open infrastructure and exhibitions instead of adding token incentives. Each decision kept the core artifact recognizable while changing the support system around it. The tradeoff is concentrated stewardship: NODE controls the IP and institutional program even though token holders control their individual Punks.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:strategic_choices:1","claim:cryptopunks:section:strategic_choices:2","claim:cryptopunks:section:strategic_choices:3"]},"operating_model":{"body":"NODE operates as a nonprofit steward of the CryptoPunks IP, collection archive, native marketplace, API and physical exhibition program. Holders transact through the original market or wrapped versions on third-party markets and may use their Punk under the current license. The original artists participate in an advisory capacity, not as a promised product team. NODE does not publish CryptoPunks-specific revenue, costs, marketplace users, licensing income or the financial contribution of its exhibitions, so cultural operation must not be rewritten as profitability.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:operating_model:1","claim:cryptopunks:section:operating_model:2","claim:cryptopunks:section:operating_model:3"]},"token_and_value_capture":{"body":"CryptoPunks has no collection-specific fungible token in the reviewed record. Holders can sell a Punk and use its associated art within the license, while NODE can create cultural, licensing and institutional programs around the IP. The native marketplace shows bids and sales but no disclosed project take rate or holder dividend. A high sale, museum acquisition or listed floor may demonstrate attention; none automatically sends cash to every holder or proves NODE earned revenue from the event.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:token_and_value_capture:1","claim:cryptopunks:section:token_and_value_capture:2","claim:cryptopunks:section:token_and_value_capture:3"]},"counterfactual":{"body":"A commercial owner could have pursued a new token, paid utility or aggressive licensing program to fund growth, but that would add incentive, dilution and delivery risk to a historically complete work. Abandoning the native market could reduce maintenance costs while increasing dependence on general marketplaces and wrappers. NODE instead chose preservation and public presentation. The record cannot show whether another owner would have created more financial value without weakening the collection’s historical clarity.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:counterfactual:1","claim:cryptopunks:section:counterfactual:2","claim:cryptopunks:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The core artifacts are durable, but stewardship decisions, marketplace maintenance and licensing remain concentrated in NODE. The original contract and wrapped ERC-721 versions create market-scope differences that can confuse listings and volume. Current unique holders, concentration, executable bid depth, wash-adjusted volume, marketplace users, NODE funding and collection-specific operating costs are unknown. Institutional recognition can support cultural relevance without protecting holders from price volatility or thin exits.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:risks_and_unknowns:1","claim:cryptopunks:section:risks_and_unknowns:2","claim:cryptopunks:section:risks_and_unknowns:3"]},"lifecycle":{"body":"CryptoPunks launched free in June 2017, moved from Larva Labs to Yuga Labs in 2022 and then to NODE in May 2025. NODE opened the full-collection 10,000 exhibition in January 2026 and continues to maintain the official market and collection record. The lifecycle call is successful cultural infrastructure: the work remains accessible, traded, licensed and actively stewarded. That label is about continuity and institutionalization, not a claim that current buyers will profit or that every Punk is liquid.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:lifecycle:1","claim:cryptopunks:section:lifecycle:2","claim:cryptopunks:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: CryptoPunks continues as a historically complete collection supported by NODE’s nonprofit preservation, marketplace and exhibition work. Watch maintenance of the market and API, license changes, NODE funding and governance, repeat institutional programs, unique buyers and sellers, executable bids and wrapped-versus-native activity. A museum acquisition or headline sale should be logged as an event, not used alone to change the lifecycle call. The next review should test whether infrastructure and audience participation remain active.","as_of":"2026-08-03","claim_ids":["claim:cryptopunks:section:outlook_and_watch:1","claim:cryptopunks:section:outlook_and_watch:2","claim:cryptopunks:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:cryptopunks:launch","type":"collection_launch","date":"2017-06-01","date_precision":"month","description":"Larva Labs released 10,000 CryptoPunks as free claims on Ethereum.","claim_ids":["claim:cryptopunks:event:launch"]},{"id":"event:cryptopunks:node-acquisition","type":"control_transfer","date":"2025-05-13","date_precision":"day","description":"NODE acquired the full CryptoPunks IP from Yuga Labs.","claim_ids":["claim:cryptopunks:event:node-acquisition"]},{"id":"event:cryptopunks:node-exhibition","type":"institutional_program","date":"2026-01-23","date_precision":"day","description":"NODE opened its Palo Alto hub with the 10,000 exhibition.","claim_ids":["claim:cryptopunks:event:node-exhibition"]}],"sources":[{"id":"source:cryptopunks:profile","title":"CryptoPunks","url":"https://nodefoundation.com/cryptopunks","publisher":"Infinite Node Foundation","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://nodefoundation.com/cryptopunks","content_hash":null,"independence_group":"node_foundation","access_method":"direct_http","direct_http_status":200},{"id":"source:cryptopunks:acquisition","title":"CryptoPunks Join the NODE Foundation","url":"https://hub.cryptopunks.app/cryptopunks-join-the-node-foundation","publisher":"Infinite Node Foundation","published_at":"2025-05-13","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://hub.cryptopunks.app/cryptopunks-join-the-node-foundation","content_hash":null,"independence_group":"node_foundation","access_method":"direct_http","direct_http_status":200},{"id":"source:cryptopunks:exhibition","title":"10,000","url":"https://nodefoundation.com/program/10000","publisher":"Infinite Node Foundation","published_at":"2026-01-23","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://nodefoundation.com/program/10000","content_hash":null,"independence_group":"node_foundation","access_method":"direct_http","direct_http_status":200},{"id":"source:cryptopunks:market","title":"CryptoPunks native marketplace","url":"https://www.cryptopunks.app/","publisher":"Infinite Node Foundation","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://www.cryptopunks.app/","content_hash":null,"independence_group":"node_foundation","access_method":"direct_http","direct_http_status":200},{"id":"source:cryptopunks:license","title":"CryptoPunks Terms","url":"https://licenseterms.cryptopunks.app/CryptoPunksTerms.pdf","publisher":"Infinite Node Foundation","published_at":"2025-08-20","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://licenseterms.cryptopunks.app/CryptoPunksTerms.pdf","content_hash":null,"independence_group":"node_foundation","access_method":"direct_http","direct_http_status":200},{"id":"source:cryptopunks:techcrunch","title":"NFT phenom CryptoPunks was just sold to a nonprofit","url":"https://techcrunch.com/2025/05/13/nft-phenom-cryptopunks-was-just-sold-to-a-nonprofit/","publisher":"TechCrunch","published_at":"2025-05-13","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://techcrunch.com/2025/05/13/nft-phenom-cryptopunks-was-just-sold-to-a-nonprofit/","content_hash":null,"independence_group":"techcrunch","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:cryptopunks:status","field_path":"status.operating_state","assertion":"NODE maintains the CryptoPunks IP, native marketplace and a current exhibition program.","value":"operating_nonprofit_stewardship","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:market","source:cryptopunks:exhibition"],"evidence_locator":"Current NODE collection, marketplace and exhibition surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:outcome","field_path":"outcome.label","assertion":"CryptoPunks remains an operating cultural and technical collection under nonprofit stewardship, without relying on a new token or roadmap.","value":"successful_cultural_infrastructure","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:cryptopunks:profile","source:cryptopunks:acquisition","source:cryptopunks:exhibition","source:cryptopunks:techcrunch"],"evidence_locator":"Current steward activity, completed IP transfer and independent acquisition coverage.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or holder-profitability claim.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"CryptoPunks contains 10,000 works released free on Ethereum in 2017.","value":"CryptoPunks contains 10,000 works released free on Ethereum in 2017.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:exhibition"],"evidence_locator":"NODE collection history and exhibition description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Matt Hall and John Watkinson created the collection through Larva Labs.","value":"Matt Hall and John Watkinson created the collection through Larva Labs.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:exhibition"],"evidence_locator":"NODE creator and exhibition credits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"Punk ownership is distinct from ownership of NODE or its programs.","value":"Punk ownership is distinct from ownership of NODE or its programs.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:cryptopunks:license","source:cryptopunks:acquisition"],"evidence_locator":"Holder terms and nonprofit IP transfer.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Yuga acquired CryptoPunks IP in 2022 and NODE acquired it in May 2025.","value":"Yuga acquired CryptoPunks IP in 2022 and NODE acquired it in May 2025.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:acquisition","source:cryptopunks:techcrunch"],"evidence_locator":"NODE chronology and independent transfer confirmation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"NODE opened a dedicated 10,000-piece exhibition in January 2026.","value":"NODE opened a dedicated 10,000-piece exhibition in January 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:exhibition"],"evidence_locator":"Current exhibition page.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"No CryptoPunks fungible token was introduced in the reviewed transition record.","value":"No CryptoPunks fungible token was introduced in the reviewed transition record.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:cryptopunks:profile","source:cryptopunks:acquisition","source:cryptopunks:market"],"evidence_locator":"Current project and transfer surfaces.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body#1","assertion":"The fixed cohort and original marketplace have remained part of the collection since launch.","value":"The fixed cohort and original marketplace have remained part of the collection since launch.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:exhibition","source:cryptopunks:market"],"evidence_locator":"NODE technical and exhibition history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body#2","assertion":"NODE preserved the collection while adding exhibition and preservation programs.","value":"NODE preserved the collection while adding exhibition and preservation programs.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:acquisition","source:cryptopunks:exhibition"],"evidence_locator":"Stewardship plan and current program.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"The effect of those choices on price and liquidity cannot be isolated from the reviewed evidence.","value":"The effect of those choices on price and liquidity cannot be isolated from the reviewed evidence.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:cryptopunks:market","source:cryptopunks:techcrunch"],"evidence_locator":"Operation and transfer coverage lacks causal market study.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"The original launch used free claims and a fixed 10,000 supply.","value":"The original launch used free claims and a fixed 10,000 supply.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:exhibition"],"evidence_locator":"Collection history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"NODE chose nonprofit preservation and exhibition as the current operating model.","value":"NODE chose nonprofit preservation and exhibition as the current operating model.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:acquisition","source:cryptopunks:exhibition"],"evidence_locator":"Acquisition mission and program.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"IP stewardship and individual token ownership remain separate layers.","value":"IP stewardship and individual token ownership remain separate layers.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:license","source:cryptopunks:acquisition"],"evidence_locator":"Holder terms and IP transfer.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"NODE maintains the collection, native marketplace and exhibition.","value":"NODE maintains the collection, native marketplace and exhibition.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:market","source:cryptopunks:exhibition"],"evidence_locator":"Current first-party surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"The original creators participate in NODE stewardship and exhibition work.","value":"The original creators participate in NODE stewardship and exhibition work.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:acquisition","source:cryptopunks:exhibition"],"evidence_locator":"Advisory and artist credits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"Collection-specific revenue, costs and marketplace users are not disclosed.","value":"Collection-specific revenue, costs and marketplace users are not disclosed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:cryptopunks:profile","source:cryptopunks:market","source:cryptopunks:exhibition"],"evidence_locator":"Current public surfaces omit these measures.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"No CryptoPunks fungible token is identified by current project sources.","value":"No CryptoPunks fungible token is identified by current project sources.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:cryptopunks:profile","source:cryptopunks:market","source:cryptopunks:license"],"evidence_locator":"Current product, market and license review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"Holders receive token control and licensed art uses rather than a revenue share.","value":"Holders receive token control and licensed art uses rather than a revenue share.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:license"],"evidence_locator":"Current holder terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"Marketplace activity is not disclosed as NODE revenue or a holder dividend.","value":"Marketplace activity is not disclosed as NODE revenue or a holder dividend.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:cryptopunks:market","source:cryptopunks:profile"],"evidence_locator":"Current market and project pages.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"NODE selected preservation and exhibition rather than a new collection roadmap.","value":"NODE selected preservation and exhibition rather than a new collection roadmap.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:acquisition","source:cryptopunks:exhibition"],"evidence_locator":"Published stewardship plan.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"The native marketplace reduces some dependence on general NFT marketplaces.","value":"The native marketplace reduces some dependence on general NFT marketplaces.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:cryptopunks:market","source:cryptopunks:profile"],"evidence_locator":"Current collection-specific market surface.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"Results under a tokenized or more commercial strategy are unobserved.","value":"Results under a tokenized or more commercial strategy are unobserved.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:cryptopunks:acquisition","source:cryptopunks:techcrunch"],"evidence_locator":"Only the chosen transfer is documented.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"NODE controls the collection IP and current official infrastructure.","value":"NODE controls the collection IP and current official infrastructure.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:acquisition","source:cryptopunks:profile","source:cryptopunks:market"],"evidence_locator":"Ownership and current operation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"Original and wrapped Punk markets are distinct technical surfaces.","value":"Original and wrapped Punk markets are distinct technical surfaces.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:market","source:cryptopunks:profile"],"evidence_locator":"Current marketplace explanation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"Current holder, liquidity and NODE financial measures are not disclosed.","value":"Current holder, liquidity and NODE financial measures are not disclosed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:cryptopunks:profile","source:cryptopunks:market","source:cryptopunks:exhibition"],"evidence_locator":"Current evidence gap.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"The collection launched in June 2017 and changed IP stewards in 2022 and 2025.","value":"The collection launched in June 2017 and changed IP stewards in 2022 and 2025.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:acquisition"],"evidence_locator":"NODE chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"NODE operated a current market and full-collection exhibition in 2026.","value":"NODE operated a current market and full-collection exhibition in 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:market","source:cryptopunks:exhibition"],"evidence_locator":"Current product surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"The success label excludes holder returns and universal liquidity.","value":"The success label excludes holder returns and universal liquidity.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:cryptopunks:market","source:cryptopunks:techcrunch"],"evidence_locator":"Market and transfer evidence do not establish those outcomes.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"Current stewardship centers on preservation, market infrastructure and exhibitions.","value":"Current stewardship centers on preservation, market infrastructure and exhibitions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:market","source:cryptopunks:exhibition"],"evidence_locator":"Current NODE program.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"License and marketplace maintenance are concrete review triggers.","value":"License and marketplace maintenance are concrete review triggers.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:license","source:cryptopunks:market"],"evidence_locator":"Current holder and transaction surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Current participation and financial durability require new measurements.","value":"Current participation and financial durability require new measurements.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:cryptopunks:profile","source:cryptopunks:market","source:cryptopunks:exhibition"],"evidence_locator":"Present sources do not provide those series.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:event:launch","field_path":"events[event:cryptopunks:launch]","assertion":"Larva Labs released 10,000 CryptoPunks as free claims on Ethereum.","value":"2017-06-01","as_of":"2017-06-01","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:profile","source:cryptopunks:exhibition"],"evidence_locator":"NODE history and exhibition.","support_direction":"supports","note":"Source precision: month.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:event:node-acquisition","field_path":"events[event:cryptopunks:node-acquisition]","assertion":"NODE acquired the full CryptoPunks IP from Yuga Labs.","value":"2025-05-13","as_of":"2025-05-13","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:acquisition","source:cryptopunks:techcrunch"],"evidence_locator":"Dated first-party and independent announcements.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:cryptopunks:event:node-exhibition","field_path":"events[event:cryptopunks:node-exhibition]","assertion":"NODE opened its Palo Alto hub with the 10,000 exhibition.","value":"2026-01-23","as_of":"2026-01-23","confidence":"high","kind":"fact","source_ids":["source:cryptopunks:exhibition"],"evidence_locator":"Current exhibition page.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T21:25:00Z","next_review_at":"2026-08-10T21:25:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["current_unique_holders","holder_concentration","executable_bid_depth","wash_adjusted_volume","native_market_users","node_collection_revenue","node_operating_costs","advisory_decision_rights"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Individual Punks, the original market contract, wrapped ERC-721 versions, holder licenses, NODE, Larva Labs and Yuga Labs have distinct rights and histories.","metric_boundary":"Bids, listings, museum acquisitions and gross secondary sales are not executable portfolio value, NODE revenue or holder yield.","editorial_guardrail":"Credit cultural and technical continuity without presenting institutional recognition as price support or a return guarantee.","explicit_unknowns":["current_unique_holders","holder_concentration","executable_bid_depth","wash_adjusted_volume","native_market_users","node_collection_revenue","node_operating_costs","advisory_decision_rights"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, adjacent-token economics and market price are kept separate.","Current market figures were intentionally not promoted because the dynamic page does not provide a stable observation timestamp in the research artifact."]}}');

INSERT INTO _nft_depth_wave_b_0096 (slug, canonical_profile) VALUES ('reddit-collectible-avatars', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:reddit-collectible-avatars","type":"nft_collection","slug":"reddit-collectible-avatars","name":"Reddit Collectible Avatars","aliases":[]},"classification":{"subtype":"social-platform avatar creator program","tags":["polygon","social_identity","fiat_onboarding","creator_program","sunset"],"chains":["Polygon"],"jurisdictions":["United States"]},"status":{"operating_state":"primary_program_sunset_residual_utility_supported","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:status"]},"outcome":{"label":"mixed_distribution_success_product_sunset","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:reddit-collectible-avatars:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Reddit Collectible Avatars are limited-edition avatar accessories created by independent artists and issued as NFTs on Polygon. Reddit hid most crypto complexity behind fiat checkout and its Vault wallet, then let owners mix avatar traits and receive special profile and comment treatments. The program is now closed to new on-platform sales. Existing holders retain licensed display rights and can use a simplified import flow for off-platform transfers, but they do not own Reddit, Snoo or the underlying creator copyrights.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:what_it_is:1","claim:reddit-collectible-avatars:section:what_it_is:2","claim:reddit-collectible-avatars:section:what_it_is:3"]},"what_happened":{"body":"Reddit announced the storefront in July 2022 and used fixed fiat prices, automatic wallets and familiar profile customization to reach people who did not need cryptocurrency first. Polygon Labs later reported more than 30 million avatars minted and more than $18 million in sales, including free distributions; those partner figures are not audited Reddit financials. Reddit sunset the creator and primary-sales program in 2025, ended access to the old Vault flow, and by February 2026 documented only existing-avatar display plus a simplified external-wallet import path.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:what_happened:1","claim:reddit-collectible-avatars:section:what_happened:2","claim:reddit-collectible-avatars:section:what_happened:3"]},"why_this_outcome":{"body":"The strongest strategic success was distribution: Reddit placed collectible ownership inside a product people already used, accepted local currency and created wallets behind the scenes. That removed the usual exchange, seed-phrase and gas steps from the first interaction. The weakness was durable economics. Free mints inflated distribution counts, later drops fragmented attention, secondary sales stayed off-platform and Reddit eventually decided the creator program was not worth continuing. The sources show the mechanism and sunset, but not Reddit’s ranked internal reasons.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:why_this_outcome:1","claim:reddit-collectible-avatars:section:why_this_outcome:2","claim:reddit-collectible-avatars:section:why_this_outcome:3"]},"strategic_choices":{"body":"Reddit chose Polygon for low-cost transactions, fixed fiat prices instead of auctions, creator-designed Snoo traits and in-product visual benefits. It paid creators from primary sales and specified secondary royalties, while never building an on-platform resale market. It later chose to end primary distribution and Vault access rather than keep a full NFT wallet and creator stack alive. These choices made entry simple, but the exit required users who wanted blockchain control to understand external wallets after the program’s most approachable interface disappeared.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:strategic_choices:1","claim:reddit-collectible-avatars:section:strategic_choices:2","claim:reddit-collectible-avatars:section:strategic_choices:3"]},"operating_model":{"body":"Reddit operated the creator intake, storefront, fiat collection, minting, Vault integration and avatar-builder utility. Independent creators supplied art under Reddit’s Snoo and marketplace terms. The current terms describe a 20% Reddit primary fee and a split of qualifying secondary royalties, but the help center says Collectible Avatars are no longer sold on Reddit. That mismatch is a lifecycle boundary, not proof that sales continue. Reddit does not publish avatar-specific revenue, costs, active users, creator retention or support burden.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:operating_model:1","claim:reddit-collectible-avatars:section:operating_model:2","claim:reddit-collectible-avatars:section:operating_model:3"]},"token_and_value_capture":{"body":"There is no Reddit Collectible Avatar fungible token. Artists historically earned primary proceeds after Reddit’s stated fees and could receive part of qualifying third-party resale royalties. Reddit collected its platform fee and part of specified secondary earnings. Holders received use, display and transfer rights rather than a company revenue share. Because Reddit does not run resale, third-party marketplaces may not honor royalties, and a nominal royalty percentage does not establish cash received by creators or Reddit.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:token_and_value_capture:1","claim:reddit-collectible-avatars:section:token_and_value_capture:2","claim:reddit-collectible-avatars:section:token_and_value_capture:3"]},"counterfactual":{"body":"Reddit could have kept a narrower avatar-only wallet and marketplace, or migrated custody tools gradually while maintaining creator sales. That might have preserved creator continuity and reduced the abrupt shift to external wallets, but it also would have retained product, compliance and support costs. A fully on-platform resale market could have improved discovery and royalty enforcement while increasing marketplace obligations. None of those alternatives were tested publicly, and distribution scale alone does not show that they would have been sustainable.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:counterfactual:1","claim:reddit-collectible-avatars:section:counterfactual:2","claim:reddit-collectible-avatars:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The NFTs remain on Polygon, but practical value depends on Reddit continuing to recognize imported wallets and avatar traits. Holders who missed the Vault transition may face access problems even when the tokens still exist onchain. The creator program’s current contractual status is confusing because legacy terms remain public after primary sales ended. Current active avatars, imported wallets, creator payouts, royalty realization, buyer retention, support claims and usable external-market liquidity are unknown. Wallet counts are not people and free distributions are not sales.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:risks_and_unknowns:1","claim:reddit-collectible-avatars:section:risks_and_unknowns:2","claim:reddit-collectible-avatars:section:risks_and_unknowns:3"]},"lifecycle":{"body":"The lifecycle has three clear stages: a July 2022 launch built around fiat onboarding; rapid expansion through paid and free Polygon distributions; and a 2025-2026 wind-down of the creator storefront and Vault. Reddit still lets existing owners use their art as avatars and import verified external wallets, so the assets and some product utility survive. The correct call is mixed distribution success followed by product sunset—not a live creator marketplace, and not total erasure of the tokens or holder licenses.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:lifecycle:1","claim:reddit-collectible-avatars:section:lifecycle:2","claim:reddit-collectible-avatars:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: existing avatars remain usable as Reddit identity items, while the creator marketplace and new-sale thesis stay closed. Watch whether Reddit keeps wallet import and avatar effects working, updates conflicting creator terms, resolves support claims, or introduces a successor digital-goods program. Measure active avatar use, verified wallets, unique secondary buyers and sellers, realized creator royalties and inaccessible legacy Vaults. Do not use 30 million historical mints as a current user count or as proof that the product succeeded economically.","as_of":"2026-08-03","claim_ids":["claim:reddit-collectible-avatars:section:outlook_and_watch:1","claim:reddit-collectible-avatars:section:outlook_and_watch:2","claim:reddit-collectible-avatars:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:reddit-collectible-avatars:partner-mints-2025-03-27","dimension":"supply","label":"Partner-reported cumulative avatars minted","value":30000000,"unit":"avatars","currency":null,"window":{"start":"2022-07-07","end":"2025-03-27","definition":"cumulative_partner_report"},"as_of":"2025-03-27","method":"Polygon Labs case study; includes paid and free distributions.","scope":{"program":"Reddit Collectible Avatars","chain":"Polygon"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:reddit-collectible-avatars:metric:partner-mints-2025-03-27"],"quality_flags":["ecosystem_partner_reported","includes_free_distributions","not_active_users","wallets_not_people"],"headline":false},{"id":"metric:reddit-collectible-avatars:partner-sales-2025-03-27","dimension":"sales","label":"Partner-reported cumulative sales","value":18000000,"unit":"usd","currency":"USD","window":{"start":"2022-07-07","end":"2025-03-27","definition":"cumulative_partner_report"},"as_of":"2025-03-27","method":"Polygon Labs case study; accounting definition not supplied.","scope":{"program":"Reddit Collectible Avatars","chain":"Polygon"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:reddit-collectible-avatars:metric:partner-sales-2025-03-27"],"quality_flags":["ecosystem_partner_reported","not_reddit_financial_statement","gross_net_definition_unknown"],"headline":false}],"events":[{"id":"event:reddit-collectible-avatars:launch","type":"product_launch","date":"2022-07-07","date_precision":"day","description":"Reddit announced its Polygon Collectible Avatar storefront.","claim_ids":["claim:reddit-collectible-avatars:event:launch"]},{"id":"event:reddit-collectible-avatars:program-sunset","type":"product_sunset","date":"2025-08-01","date_precision":"month","description":"Reddit announced the sunset of the Avatar Creator Program during August 2025.","claim_ids":["claim:reddit-collectible-avatars:event:program-sunset"]},{"id":"event:reddit-collectible-avatars:current-support","type":"residual_support","date":"2026-02-04","date_precision":"day","description":"Reddit documented post-sunset avatar use and wallet import.","claim_ids":["claim:reddit-collectible-avatars:event:current-support"]}],"sources":[{"id":"source:reddit-collectible-avatars:launch","title":"Blockchain-Backed Collectible Avatars Coming to Reddit via New Storefront","url":"https://redditinc.com/news/blockchain-backed-collectible-avatars-coming-to-reddit-via-new-storefront","publisher":"Reddit","published_at":"2022-07-07","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://redditinc.com/news/blockchain-backed-collectible-avatars-coming-to-reddit-via-new-storefront","content_hash":null,"independence_group":"reddit","access_method":"direct_http","direct_http_status":200},{"id":"source:reddit-collectible-avatars:current-help","title":"Collectible Avatars on Reddit","url":"https://support.reddithelp.com/hc/en-us/articles/6213835889044-Collectible-Avatars-on-Reddit","publisher":"Reddit","published_at":"2026-02-04","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://support.reddithelp.com/hc/en-us/articles/6213835889044-Collectible-Avatars-on-Reddit","content_hash":null,"independence_group":"reddit","access_method":"indexed_browser_snapshot","direct_http_status":403},{"id":"source:reddit-collectible-avatars:import","title":"How to import my Collectible Avatar and manage my verified wallets","url":"https://support.reddithelp.com/hc/en-us/articles/40643146058900-How-to-import-my-Collectible-Avatar-and-manage-my-verified-wallet-s-associated-with-my-account","publisher":"Reddit","published_at":"2026-02-04","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://support.reddithelp.com/hc/en-us/articles/40643146058900-How-to-import-my-Collectible-Avatar-and-manage-my-verified-wallet-s-associated-with-my-account","content_hash":null,"independence_group":"reddit","access_method":"indexed_browser_snapshot","direct_http_status":403},{"id":"source:reddit-collectible-avatars:terms","title":"Creator Terms","url":"https://redditinc.com/policies/creator-terms","publisher":"Reddit","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://redditinc.com/policies/creator-terms","content_hash":null,"independence_group":"reddit","access_method":"direct_http","direct_http_status":200},{"id":"source:reddit-collectible-avatars:polygon","title":"How Reddit onboarded millions with Collectible Avatars","url":"https://polygon.technology/blog/how-reddit-crypto-pilled-the-covid-generation-with-easy-to-purchase-collectible-avatars-on-polygon-pos","publisher":"Polygon Labs","published_at":"2025-03-27","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://polygon.technology/blog/how-reddit-crypto-pilled-the-covid-generation-with-easy-to-purchase-collectible-avatars-on-polygon-pos","content_hash":null,"independence_group":"polygon_labs","access_method":"direct_http","direct_http_status":200},{"id":"source:reddit-collectible-avatars:pcgamer","title":"Reddit''s NFTs are disappearing in less than 30 days","url":"https://www.pcgamer.com/games/oh-no-all-of-reddits-nfts-are-disappearing-in-less-than-30-days-someone-do-something/","publisher":"PC Gamer","published_at":"2025-12-04","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://www.pcgamer.com/games/oh-no-all-of-reddits-nfts-are-disappearing-in-less-than-30-days-someone-do-something/","content_hash":null,"independence_group":"future_plc","access_method":"direct_http","direct_http_status":200},{"id":"source:reddit-collectible-avatars:usenix","title":"It was honestly just gambling: risks and user understanding in NFT communities","url":"https://www.usenix.org/system/files/soups2024-bouma-sims.pdf","publisher":"USENIX Association","published_at":"2024-08-01","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://www.usenix.org/system/files/soups2024-bouma-sims.pdf","content_hash":null,"independence_group":"usenix","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:reddit-collectible-avatars:status","field_path":"status.operating_state","assertion":"Reddit no longer sells Collectible Avatars, but still supports avatar display and a simplified off-platform wallet-import flow.","value":"primary_program_sunset_residual_utility_supported","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:import","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Current Reddit help pages and independent coverage of the 2025-2026 wind-down.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:outcome","field_path":"outcome.label","assertion":"The program achieved unusually broad blockchain distribution, then ended primary sales while preserving narrower display and transfer support.","value":"mixed_distribution_success_product_sunset","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:reddit-collectible-avatars:launch","source:reddit-collectible-avatars:polygon","source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Original product design, partner-reported scale and current post-sunset support.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or holder-profitability claim.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Collectible Avatars are artist-made limited editions issued on Polygon.","value":"Collectible Avatars are artist-made limited editions issued on Polygon.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:launch","source:reddit-collectible-avatars:current-help"],"evidence_locator":"Original launch and current help descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Reddit integrated fiat purchase, Vault custody and avatar-builder utility.","value":"Reddit integrated fiat purchase, Vault custody and avatar-builder utility.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:launch"],"evidence_locator":"Launch purchase and wallet flow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"Holder rights are licenses and do not transfer Reddit or creator copyrights.","value":"Holder rights are licenses and do not transfer Reddit or creator copyrights.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:terms","source:reddit-collectible-avatars:current-help"],"evidence_locator":"Creator and collector rights sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Reddit launched the storefront on July 7, 2022 with fiat pricing and Vault wallets.","value":"Reddit launched the storefront on July 7, 2022 with fiat pricing and Vault wallets.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:launch"],"evidence_locator":"Dated launch announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"Polygon Labs reported more than 30 million mints and more than $18 million in sales by March 2025.","value":"Polygon Labs reported more than 30 million mints and more than $18 million in sales by March 2025.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:polygon"],"evidence_locator":"Partner case study; self-reported program scale.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"Primary sales ended while residual display and off-platform transfer support remained.","value":"Primary sales ended while residual display and off-platform transfer support remained.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:import","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Current help and wind-down coverage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body#1","assertion":"Embedded fiat purchase and automatic wallet creation reduced onboarding friction.","value":"Embedded fiat purchase and automatic wallet creation reduced onboarding friction.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:reddit-collectible-avatars:launch","source:reddit-collectible-avatars:polygon"],"evidence_locator":"Launch mechanics and partner case study.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body#2","assertion":"The final support model excludes on-platform primary and secondary sales.","value":"The final support model excludes on-platform primary and secondary sales.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:terms"],"evidence_locator":"Current help and marketplace limitations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"Reddit has not published a ranked financial or product explanation for the sunset.","value":"Reddit has not published a ranked financial or product explanation for the sunset.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Current operator page and independent closure report.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"Reddit chose Polygon, fixed fiat pricing and integrated avatar utility.","value":"Reddit chose Polygon, fixed fiat pricing and integrated avatar utility.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:launch"],"evidence_locator":"Product-design sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"Creator terms define primary fees and secondary-royalty economics.","value":"Creator terms define primary fees and secondary-royalty economics.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:terms"],"evidence_locator":"Creator Earnings and Reddit Fees sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"The wind-down shifted blockchain control toward external-wallet import.","value":"The wind-down shifted blockchain control toward external-wallet import.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:reddit-collectible-avatars:import","source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Current import and closure process.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"Reddit historically operated creator review, checkout, minting and avatar utility.","value":"Reddit historically operated creator review, checkout, minting and avatar utility.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:launch","source:reddit-collectible-avatars:terms"],"evidence_locator":"Launch and creator terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"The terms define a 20% primary fee while current help says new Reddit sales have ended.","value":"The terms define a 20% primary fee while current help says new Reddit sales have ended.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:terms","source:reddit-collectible-avatars:current-help"],"evidence_locator":"Payment terms versus current product status.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"Program-specific revenue, costs and user retention are not disclosed.","value":"Program-specific revenue, costs and user retention are not disclosed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:terms"],"evidence_locator":"Current public documentation omits these fields.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"No program-specific fungible token is identified in current Reddit product terms.","value":"No program-specific fungible token is identified in current Reddit product terms.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:terms"],"evidence_locator":"Current product and creator terms.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"Creator and Reddit fee splits are defined for primary and qualifying secondary activity.","value":"Creator and Reddit fee splits are defined for primary and qualifying secondary activity.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:terms"],"evidence_locator":"Payment Terms section.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"Collectors receive licensed utility rather than Reddit revenue rights.","value":"Collectors receive licensed utility rather than Reddit revenue rights.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:terms"],"evidence_locator":"Collector rights and creator-license sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"The actual path ended primary sales and moved transfers off-platform.","value":"The actual path ended primary sales and moved transfers off-platform.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:import","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Current post-sunset flow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"Reddit never supported its own secondary-sales market in the reviewed terms.","value":"Reddit never supported its own secondary-sales market in the reviewed terms.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:terms","source:reddit-collectible-avatars:current-help"],"evidence_locator":"Marketplace acknowledgements and current help.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"Costs and outcomes of narrower or fuller alternatives are not public.","value":"Costs and outcomes of narrower or fuller alternatives are not public.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Only the chosen wind-down is documented.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"Current utility depends on Reddit account and verified-wallet integration.","value":"Current utility depends on Reddit account and verified-wallet integration.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:import"],"evidence_locator":"Current display and import workflow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"Independent coverage documented access risk around the Vault deadline.","value":"Independent coverage documented access risk around the Vault deadline.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"December 2025 wind-down report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"Current usage, payout and liquidity measures are not disclosed.","value":"Current usage, payout and liquidity measures are not disclosed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:terms","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Current evidence gap.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"The program launched in July 2022 and scaled through paid and free distributions.","value":"The program launched in July 2022 and scaled through paid and free distributions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:launch","source:reddit-collectible-avatars:polygon"],"evidence_locator":"Launch and partner scale report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"Reddit later ended sales and its old Vault flow.","value":"Reddit later ended sales and its old Vault flow.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:import","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Current support and independent wind-down record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Existing display and off-platform transfer rights survive the sales shutdown.","value":"Existing display and off-platform transfer rights survive the sales shutdown.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:terms"],"evidence_locator":"Current collector rights.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"Current residual utility is display plus imported-wallet support.","value":"Current residual utility is display plus imported-wallet support.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:import"],"evidence_locator":"Current help workflow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"Historical mint scale includes free distributions and is not current active usage.","value":"Historical mint scale includes free distributions and is not current active usage.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:reddit-collectible-avatars:polygon"],"evidence_locator":"Partner case-study methodology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Current active use, royalties and access failures need new evidence.","value":"Current active use, royalties and access failures need new evidence.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Current sources do not quantify them.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:metric:partner-mints-2025-03-27","field_path":"metrics[metric:reddit-collectible-avatars:partner-mints-2025-03-27]","assertion":"Polygon Labs reported more than 30 million Collectible Avatars minted.","value":30000000,"as_of":"2025-03-27","confidence":"medium","kind":"fact","source_ids":["source:reddit-collectible-avatars:polygon"],"evidence_locator":"Partner case-study scale paragraph.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:metric:partner-sales-2025-03-27","field_path":"metrics[metric:reddit-collectible-avatars:partner-sales-2025-03-27]","assertion":"Polygon Labs reported more than $18 million in program sales.","value":18000000,"as_of":"2025-03-27","confidence":"medium","kind":"fact","source_ids":["source:reddit-collectible-avatars:polygon"],"evidence_locator":"Partner case-study scale paragraph.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:event:launch","field_path":"events[event:reddit-collectible-avatars:launch]","assertion":"Reddit announced its Polygon Collectible Avatar storefront.","value":"2022-07-07","as_of":"2022-07-07","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:launch"],"evidence_locator":"Dated launch announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:event:program-sunset","field_path":"events[event:reddit-collectible-avatars:program-sunset]","assertion":"Reddit announced the sunset of the Avatar Creator Program during August 2025.","value":"2025-08-01","as_of":"2025-08-01","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:pcgamer"],"evidence_locator":"Independent report reproducing the operator announcement at month precision.","support_direction":"supports","note":"Source precision: month.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:reddit-collectible-avatars:event:current-support","field_path":"events[event:reddit-collectible-avatars:current-support]","assertion":"Reddit documented post-sunset avatar use and wallet import.","value":"2026-02-04","as_of":"2026-02-04","confidence":"high","kind":"fact","source_ids":["source:reddit-collectible-avatars:current-help","source:reddit-collectible-avatars:import"],"evidence_locator":"Current help-center updates.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T21:25:00Z","next_review_at":"2026-08-10T21:25:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["current_active_avatar_users","verified_wallet_count","creator_payouts","realized_secondary_royalties","reddit_program_revenue","program_operating_costs","legacy_vault_access_failures","secondary_market_liquidity"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Individual avatar series, creators, collectors, Reddit, Vault wallets, Polygon and third-party marketplaces have separate rights and economics.","metric_boundary":"Historical mints include free distributions; wallets are not people; partner-reported sales are not Reddit revenue or current product usage.","editorial_guardrail":"Describe the broad onboarding result and the later sunset together. Do not call residual display support a live creator marketplace.","explicit_unknowns":["current_active_avatar_users","verified_wallet_count","creator_payouts","realized_secondary_royalties","reddit_program_revenue","program_operating_costs","legacy_vault_access_failures","secondary_market_liquidity"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, adjacent-token economics and market price are kept separate.","Reddit help pages were browser-indexed but returned direct HTTP 403 during automated access. The current help language takes precedence over older marketplace language in still-public creator terms."]}}');

INSERT INTO _nft_depth_wave_b_0096 (slug, canonical_profile) VALUES ('moonbirds', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:moonbirds","type":"nft_collection","slug":"moonbirds","name":"Moonbirds","aliases":[]},"classification":{"subtype":"acquired profile-picture IP and consumer-products brand","tags":["ethereum","pfp","acquired","physical_collectibles","birb_token","reboot"],"chains":["Ethereum","Solana","TON"],"jurisdictions":["United States"]},"status":{"operating_state":"operating_reboot_with_token_and_products","as_of":"2026-08-03","claim_ids":["claim:moonbirds:status"]},"outcome":{"label":"middling_reboot_execution_visible_economics_unverified","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:moonbirds:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Moonbirds is a 10,000-piece Ethereum profile-picture collection launched by PROOF in April 2022. Orange Cap Games now owns the Moonbirds, Mythics and Oddities IP and is rebuilding the brand around physical collectibles, digital campaigns and the Solana-based BIRB token. The original NFTs remain on Ethereum and can use a legacy portal. BIRB, Vibes trading cards, related soulbound tokens and the operating company are separate assets and products; a Moonbird is not equity in Orange Cap Games or an automatic claim on all brand revenue.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:what_it_is:1","claim:moonbirds:section:what_it_is:2","claim:moonbirds:section:what_it_is:3"]},"what_happened":{"body":"PROOF launched Moonbirds with nesting and member benefits, then Yuga Labs acquired PROOF in 2024. Yuga sold the Moonbirds IP to Orange Cap Games in May 2025 as it narrowed its portfolio. Orange Cap connected the birds to its Vibes trading-card business, expanded the IP across several chains and launched BIRB in January 2026. Current pages show nesting rewards, physical products and tournament updates. This is a real operating reboot, but a new owner and token do not erase the collection’s earlier decline or prove renewed holder demand.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:what_happened:1","claim:moonbirds:section:what_happened:2","claim:moonbirds:section:what_happened:3"]},"why_this_outcome":{"body":"Moonbirds lost momentum while moving from founder-led PROOF to Yuga and then to a third owner whose specialty is physical collectibles. Orange Cap’s strategic answer was distribution: use an already recognizable crypto character in cards, retail, digital campaigns and a fungible coordination token. That gives the IP more product surfaces than a static profile picture and can reach people outside NFT markets. The approach may support a turnaround, but the reviewed figures cover the wider Vibes and birb ecosystem rather than isolating what changed for original Moonbirds holders.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:why_this_outcome:1","claim:moonbirds:section:why_this_outcome:2","claim:moonbirds:section:why_this_outcome:3"]},"strategic_choices":{"body":"The original team chose nesting and gated community benefits. Orange Cap kept a legacy management portal but shifted the growth model toward consumer products, cross-chain campaigns, BIRB rewards and a token launchpad. It acquired historical IP instead of inventing a new mascot, then used Vibes distribution as the commercial engine. The tradeoff is complexity: an Ethereum NFT holder now faces Solana token mechanics, product-company execution and several adjacent communities. More reach does not guarantee that value returns to the original collection.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:strategic_choices:1","claim:moonbirds:section:strategic_choices:2","claim:moonbirds:section:strategic_choices:3"]},"operating_model":{"body":"Orange Cap Games operates the Moonbirds IP and the wider consumer-products business. It develops Vibes trading cards, works with distributors and retailers, maintains current Moonbirds and rewards sites and presents BIRB as a coordination layer around the brand. NFT owners can use the legacy portal and optionally nest eligible assets for monthly token allocations. The company self-reports meaningful card sales, but does not publish audited Moonbirds-specific revenue, product margins, acquisition cost, royalty receipts, staffing or the share of customers who also hold an original NFT.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:operating_model:1","claim:moonbirds:section:operating_model:2","claim:moonbirds:section:operating_model:3"]},"token_and_value_capture":{"body":"Moonbirds now has an adjacent Solana token, BIRB. The current nesting page offers eligible Moonbirds monthly allocations and displays 16,527 BIRB remaining per Moonbird at the review date, subject to uninterrupted nesting and program rules. Orange Cap says physical collectibles are the revenue engine and BIRB coordinates culture and distribution. That is the operator’s thesis, not a legal revenue share: owning the NFT or token does not grant equity, audited cash flow or a guaranteed claim on Vibes sales, and token rewards can fall in value.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:token_and_value_capture:1","claim:moonbirds:section:token_and_value_capture:2","claim:moonbirds:section:token_and_value_capture:3"]},"counterfactual":{"body":"A collection-only strategy could have preserved a simpler Ethereum identity and reduced confusion between PROOF, Yuga, Orange Cap, Vibes and BIRB, but it would have left fewer distribution and revenue experiments. Orange Cap could also publish audited collection-level economics and a clear allocation bridge from products to holders. That would make the model easier to judge without changing the consumer strategy. The record does not establish whether a token-free reboot or greater disclosure would improve demand, retention or company performance.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:counterfactual:1","claim:moonbirds:section:counterfactual:2","claim:moonbirds:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The reboot depends on Orange Cap executing physical products while keeping crypto communities engaged. BIRB adds market, allocation, custody and regulatory risk; nesting adds eligibility rules and operator dependence. Self-reported card sales and wallet growth may be accurate without proving repeat buyers, margins or original-holder retention. Current Moonbirds owners, concentration, unique buyers and sellers, executable bid depth, royalty income, nesting participation, BIRB claims and sales attributable to Moonbirds remain unknown. Ownership churn also raises the risk of another strategic handoff.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:risks_and_unknowns:1","claim:moonbirds:section:risks_and_unknowns:2","claim:moonbirds:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Moonbirds launched under PROOF in April 2022, passed to Yuga Labs through the 2024 PROOF acquisition and moved again to Orange Cap Games in May 2025. Orange Cap launched a consumer-products and token reboot, with live BIRB nesting and current Vibes releases in 2026. The collection is therefore operating, not abandoned, but its lifecycle remains a middling reboot: execution is visible while recovery in the original NFT cohort is not. The next call must compare retained holders and collection demand with the broader brand’s growth.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:lifecycle:1","claim:moonbirds:section:lifecycle:2","claim:moonbirds:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Orange Cap keeps shipping consumer collectibles and BIRB campaigns while Moonbirds functions as the historical IP anchor. Watch Vibes sell-through and repeat releases, audited company revenue and margins, Moonbirds-specific buyers and sellers, nesting participation, BIRB claims and unlocks, retailer expansion, license changes and another IP transfer. A larger cross-chain wallet count or token rally is not the same as retained Ethereum NFT holders. The strongest upgrade signal would be repeat consumer demand plus transparent collection-level benefits that do not depend on emissions.","as_of":"2026-08-03","claim_ids":["claim:moonbirds:section:outlook_and_watch:1","claim:moonbirds:section:outlook_and_watch:2","claim:moonbirds:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:moonbirds:vibes-cards-2026-01-28","dimension":"sales","label":"Operator-reported Vibes cards sold","value":8600000,"unit":"cards","currency":null,"window":{"start":"2025-01-28","end":"2026-01-28","definition":"operator_reported_trailing_12_months"},"as_of":"2026-01-28","method":"Orange Cap Games operating thesis, repeated by a dated independent publication.","scope":{"company":"Orange Cap Games","product":"Vibes TCG"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:moonbirds:metric:vibes-cards-2026-01-28"],"quality_flags":["operator_reported","independent_republication_not_audit","not_audited","not_moonbirds_nft_specific"],"headline":false},{"id":"metric:moonbirds:vibes-primary-sales-2026-01-28","dimension":"sales","label":"Operator-reported Vibes gross primary sales","value":6000000,"unit":"usd","currency":"USD","window":{"start":"2025-01-28","end":"2026-01-28","definition":"operator_reported_trailing_12_months"},"as_of":"2026-01-28","method":"Orange Cap Games operating thesis, repeated by a dated independent publication.","scope":{"company":"Orange Cap Games","product":"Vibes TCG"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:moonbirds:metric:vibes-primary-sales-2026-01-28"],"quality_flags":["operator_reported","independent_republication_not_audit","gross_not_net","not_audited","not_moonbirds_nft_specific"],"headline":false}],"events":[{"id":"event:moonbirds:launch","type":"collection_launch","date":"2022-04-01","date_precision":"month","description":"PROOF launched the 10,000-piece Moonbirds collection during April 2022.","claim_ids":["claim:moonbirds:event:launch"]},{"id":"event:moonbirds:orange-cap-acquisition","type":"control_transfer","date":"2025-05-30","date_precision":"day","description":"Orange Cap Games acquired the Moonbirds IP from Yuga Labs.","claim_ids":["claim:moonbirds:event:orange-cap-acquisition"]},{"id":"event:moonbirds:birb-launch","type":"token_launch","date":"2026-01-29","date_precision":"day","description":"Moonbirds launched the BIRB token and current nesting program.","claim_ids":["claim:moonbirds:event:birb-launch"]}],"sources":[{"id":"source:moonbirds:legacy","title":"Moonbird collection record","url":"https://www.proof.xyz/moonbirds/2026","publisher":"PROOF Holdings","published_at":"2022-04-16","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://www.proof.xyz/moonbirds/2026","content_hash":null,"independence_group":"proof_collective","access_method":"direct_http","direct_http_status":200},{"id":"source:moonbirds:current","title":"A New Chapter for Moonbirds","url":"https://moonbirds.com/","publisher":"Moonbirds / Orange Cap Games","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://moonbirds.com/","content_hash":null,"independence_group":"orange_cap_games","access_method":"direct_http","direct_http_status":200},{"id":"source:moonbirds:thesis","title":"The Birbillions Thesis","url":"https://birbpad.fun/docs","publisher":"Orange Cap Games","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://birbpad.fun/docs"