rence","source_ids":["source:moonbirds:current","source:moonbirds:thesis","source:moonbirds:nesting","source:moonbirds:vibes","source:moonbirds:acquisition"],"evidence_locator":"Current execution compared with the independently confirmed 2025 IP transfer.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or holder-profitability claim.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Moonbirds launched as a 10,000-piece Ethereum collection in April 2022.","value":"Moonbirds launched as a 10,000-piece Ethereum collection in April 2022.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:legacy","source:moonbirds:acquisition"],"evidence_locator":"Original collection record and independent ownership history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Orange Cap Games owns and operates the Moonbirds IP family.","value":"Orange Cap Games owns and operates the Moonbirds IP family.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:current","source:moonbirds:thesis","source:moonbirds:acquisition"],"evidence_locator":"Current first-party and independent acquisition record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"The Ethereum NFT, Solana BIRB token and physical products are separate instruments.","value":"The Ethereum NFT, Solana BIRB token and physical products are separate instruments.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:moonbirds:thesis","source:moonbirds:nesting","source:moonbirds:vibes"],"evidence_locator":"Current product and token surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Yuga acquired PROOF in 2024 and sold Moonbirds IP to Orange Cap Games in May 2025.","value":"Yuga acquired PROOF in 2024 and sold Moonbirds IP to Orange Cap Games in May 2025.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:acquisition"],"evidence_locator":"Independent ownership chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"Orange Cap launched BIRB and connected Moonbirds to its consumer-products strategy in 2026.","value":"Orange Cap launched BIRB and connected Moonbirds to its consumer-products strategy in 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:thesis","source:moonbirds:nesting","source:moonbirds:token-coverage"],"evidence_locator":"Current thesis, rewards surface and independent launch coverage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"Current execution does not by itself establish NFT-holder retention or recovery.","value":"Current execution does not by itself establish NFT-holder retention or recovery.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:moonbirds:current","source:moonbirds:vibes","source:moonbirds:acquisition"],"evidence_locator":"Operation is visible; cohort recovery measures are absent.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body#1","assertion":"Moonbirds changed controlling IP owners twice after launch.","value":"Moonbirds changed controlling IP owners twice after launch.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:acquisition"],"evidence_locator":"Independent acquisition history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body#2","assertion":"Orange Cap centers physical distribution and repeat consumer products in its strategy.","value":"Orange Cap centers physical distribution and repeat consumer products in its strategy.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:thesis","source:moonbirds:vibes"],"evidence_locator":"Birbillions thesis and current product program.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"Current operating figures are not isolated to the original Moonbirds NFT cohort.","value":"Current operating figures are not isolated to the original Moonbirds NFT cohort.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:moonbirds:thesis","source:moonbirds:vibes"],"evidence_locator":"Self-reported metrics span products and chains.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"The original collection used nesting and holder benefits.","value":"The original collection used nesting and holder benefits.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:legacy","source:moonbirds:current"],"evidence_locator":"Legacy collection and current portal.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"Orange Cap chose physical distribution, cross-chain campaigns and BIRB as the reboot model.","value":"Orange Cap chose physical distribution, cross-chain campaigns and BIRB as the reboot model.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:thesis","source:moonbirds:nesting","source:moonbirds:vibes"],"evidence_locator":"Current operating thesis and products.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"Cross-product reach and NFT-holder value capture remain separate outcomes.","value":"Cross-product reach and NFT-holder value capture remain separate outcomes.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:moonbirds:thesis","source:moonbirds:nesting"],"evidence_locator":"Token and company model compared with holder rewards.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"Orange Cap runs current product, collection and BIRB reward surfaces.","value":"Orange Cap runs current product, collection and BIRB reward surfaces.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:current","source:moonbirds:thesis","source:moonbirds:nesting","source:moonbirds:vibes"],"evidence_locator":"Current first-party pages.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"Eligible NFT owners can nest assets for recurring BIRB allocations.","value":"Eligible NFT owners can nest assets for recurring BIRB allocations.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:nesting"],"evidence_locator":"Current nesting rules and displayed allocations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"Moonbirds-specific financial and customer-overlap data are not disclosed.","value":"Moonbirds-specific financial and customer-overlap data are not disclosed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:moonbirds:thesis","source:moonbirds:vibes","source:moonbirds:current"],"evidence_locator":"Current company disclosures omit these fields.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"Eligible nested Moonbirds can receive monthly BIRB allocations under current rules.","value":"Eligible nested Moonbirds can receive monthly BIRB allocations under current rules.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:nesting"],"evidence_locator":"Current BIRB Nesting page.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"Orange Cap describes physical products as revenue and BIRB as coordination.","value":"Orange Cap describes physical products as revenue and BIRB as coordination.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:thesis"],"evidence_locator":"Birbillions business thesis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"No equity or guaranteed revenue share is stated for NFT or token holders.","value":"No equity or guaranteed revenue share is stated for NFT or token holders.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:moonbirds:thesis","source:moonbirds:nesting"],"evidence_locator":"Current company and reward descriptions.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"The chosen reboot spans several owners, products and chains.","value":"The chosen reboot spans several owners, products and chains.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:acquisition","source:moonbirds:thesis","source:moonbirds:nesting"],"evidence_locator":"Ownership and current strategy.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"Current reporting does not isolate collection-level economics.","value":"Current reporting does not isolate collection-level economics.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:thesis","source:moonbirds:vibes"],"evidence_locator":"Self-reported business metrics are broader than Moonbirds.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"Outcomes under a token-free or more transparent alternative are unobserved.","value":"Outcomes under a token-free or more transparent alternative are unobserved.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:moonbirds:thesis","source:moonbirds:acquisition"],"evidence_locator":"Only the chosen path is documented.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"Current strategy combines physical execution with token and nesting mechanics.","value":"Current strategy combines physical execution with token and nesting mechanics.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:thesis","source:moonbirds:nesting","source:moonbirds:vibes"],"evidence_locator":"Current operating model.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"Self-reported business figures are not audited collection-level results.","value":"Self-reported business figures are not audited collection-level results.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:moonbirds:thesis"],"evidence_locator":"Evidence of Execution section and its scope.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"Current NFT market, rewards and collection economics are not disclosed.","value":"Current NFT market, rewards and collection economics are not disclosed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:moonbirds:current","source:moonbirds:nesting","source:moonbirds:vibes"],"evidence_locator":"Current evidence gap.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"The collection passed from PROOF to Yuga and then Orange Cap.","value":"The collection passed from PROOF to Yuga and then Orange Cap.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:legacy","source:moonbirds:acquisition"],"evidence_locator":"Launch and independent ownership chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"Current 2026 BIRB and Vibes programs show active operation.","value":"Current 2026 BIRB and Vibes programs show active operation.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:nesting","source:moonbirds:vibes","source:moonbirds:thesis"],"evidence_locator":"Current first-party products.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Original-cohort recovery remains unmeasured.","value":"Original-cohort recovery remains unmeasured.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:moonbirds:current","source:moonbirds:thesis"],"evidence_locator":"Current operator pages lack cohort outcomes.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"Orange Cap currently positions products and distribution as the growth engine.","value":"Orange Cap currently positions products and distribution as the growth engine.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:thesis","source:moonbirds:vibes"],"evidence_locator":"Current strategy and release cadence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"BIRB nesting and cross-chain campaigns create measurable but separate watch surfaces.","value":"BIRB nesting and cross-chain campaigns create measurable but separate watch surfaces.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:moonbirds:nesting","source:moonbirds:thesis"],"evidence_locator":"Current reward and wallet claims.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Collection-specific retention and non-emission value capture require new evidence.","value":"Collection-specific retention and non-emission value capture require new evidence.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:moonbirds:current","source:moonbirds:thesis","source:moonbirds:nesting"],"evidence_locator":"Current evidence gap.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:metric:vibes-cards-2026-01-28","field_path":"metrics[metric:moonbirds:vibes-cards-2026-01-28]","assertion":"Orange Cap reported more than 8.6 million Vibes cards sold during the prior year.","value":8600000,"as_of":"2026-01-28","confidence":"medium","kind":"fact","source_ids":["source:moonbirds:thesis","source:moonbirds:odaily"],"evidence_locator":"Evidence of Execution section and dated Odaily summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:metric:vibes-primary-sales-2026-01-28","field_path":"metrics[metric:moonbirds:vibes-primary-sales-2026-01-28]","assertion":"Orange Cap reported more than $6 million in Vibes gross primary sales during the prior year.","value":6000000,"as_of":"2026-01-28","confidence":"medium","kind":"fact","source_ids":["source:moonbirds:thesis","source:moonbirds:odaily"],"evidence_locator":"Evidence of Execution section and dated Odaily summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:event:launch","field_path":"events[event:moonbirds:launch]","assertion":"PROOF launched the 10,000-piece Moonbirds collection during April 2022.","value":"2022-04-01","as_of":"2022-04-01","confidence":"high","kind":"fact","source_ids":["source:moonbirds:legacy","source:moonbirds:acquisition"],"evidence_locator":"Collection record and independent history at month precision.","support_direction":"supports","note":"Source precision: month.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:event:orange-cap-acquisition","field_path":"events[event:moonbirds:orange-cap-acquisition]","assertion":"Orange Cap Games acquired the Moonbirds IP from Yuga Labs.","value":"2025-05-30","as_of":"2025-05-30","confidence":"high","kind":"fact","source_ids":["source:moonbirds:acquisition"],"evidence_locator":"Dated independent acquisition report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:moonbirds:event:birb-launch","field_path":"events[event:moonbirds:birb-launch]","assertion":"Moonbirds launched the BIRB token and current nesting program.","value":"2026-01-29","as_of":"2026-01-29","confidence":"high","kind":"fact","source_ids":["source:moonbirds:nesting","source:moonbirds:token-coverage"],"evidence_locator":"Current claim interface and independent launch digest.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T21:25:00Z","next_review_at":"2026-08-10T21:25:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"medium","unsourced_fields":["moonbirds_unique_holders","holder_concentration","unique_buyers_and_sellers","executable_bid_depth","royalty_revenue","nesting_participation","birb_claims_and_realization","moonbirds_attributable_sales","company_margin","acquisition_price"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Moonbirds NFTs, Mythics, Oddities, PROOF, Yuga Labs, Orange Cap Games, Vibes products, BIRB and cross-chain campaigns have separate ownership and economics.","metric_boundary":"Company card sales, cross-chain wallets and token allocations are not Moonbirds NFT revenue, retained holders, profit or guaranteed realizable value.","editorial_guardrail":"Recognize current reboot execution while keeping operator self-reports, token incentives and original NFT-cohort outcomes separate.","explicit_unknowns":["moonbirds_unique_holders","holder_concentration","unique_buyers_and_sellers","executable_bid_depth","royalty_revenue","nesting_participation","birb_claims_and_realization","moonbirds_attributable_sales","company_margin","acquisition_price"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, adjacent-token economics and market price are kept separate.","Operator product metrics are retained with explicit non-collection and unaudited flags. No current NFT floor is promoted because a listed floor is not executable liquidity."]}}');

INSERT INTO _nft_depth_wave_b_0096 (slug, canonical_profile) VALUES ('kraken-nft-marketplace', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:kraken-nft-marketplace","type":"nft_collection","slug":"kraken-nft-marketplace","name":"Kraken NFT Marketplace","aliases":[]},"classification":{"subtype":"closed centralized multi-chain NFT marketplace","tags":["marketplace","custodial","multi_chain","closed","resource_reallocation"],"chains":["Ethereum","Polygon","Solana"],"jurisdictions":[]},"status":{"operating_state":"closed","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:status"]},"outcome":{"label":"failed_product_closed_orderly_wind_down","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:kraken-nft-marketplace:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Kraken NFT was a custodial marketplace embedded in the Kraken exchange account, not an NFT collection. It let customers browse, buy, sell and hold NFTs from several chains while funding purchases with supported cash or crypto balances. Kraken internalized some transfers so it could advertise zero network gas fees for marketplace trades. The product is now closed. NFTs bought there were assets under their own contracts; they were not Kraken shares, and closure did not erase an NFT that a customer withdrew to a self-custodial wallet.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:what_it_is:1","claim:kraken-nft-marketplace:section:what_it_is:2","claim:kraken-nft-marketplace:section:what_it_is:3"]},"what_happened":{"body":"Kraken announced the product in May 2022 and opened public beta on December 22 with more than 110 collections, multiple funding currencies and creator-earnings support. It later added chains and collections, but did not publish marketplace-specific users, volume or revenue. On November 27, 2024 Kraken ended listings, bids, purchases and sales and moved the service to withdrawal-only mode. After a three-month exit window, it fully shut the marketplace on February 27, 2025 and said resources would move to other products and services.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:what_happened:1","claim:kraken-nft-marketplace:section:what_happened:2","claim:kraken-nft-marketplace:section:what_happened:3"]},"why_this_outcome":{"body":"Kraken’s verified reason was portfolio priority: the company chose to shift people and resources into other products. The marketplace attempted to differentiate through exchange funding rails, custody convenience, broad collection support and zero gas fees, but the public record does not show that these features created enough usage or economics to keep funding. Weak NFT demand and specialist competition are plausible context, not proven internal causes. The strongest causal statement is therefore strategic reallocation after an undisclosed product-performance test.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:why_this_outcome:1","claim:kraken-nft-marketplace:section:why_this_outcome:2","claim:kraken-nft-marketplace:section:why_this_outcome:3"]},"strategic_choices":{"body":"Kraken chose a centralized account and custody model instead of a wallet-first aggregator. It subsidized or internalized network movements for in-platform trades, accepted many payment currencies and supported creator earnings across a broad catalog. At closure it stopped trading before custody access, giving customers a defined withdrawal window and pointing them to self-custody. This reduced abrupt asset lock-in, but the hard deadline meant users who did not act would lose Kraken access to those NFTs. The company chose a clean product exit over indefinite maintenance.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:strategic_choices:1","claim:kraken-nft-marketplace:section:strategic_choices:2","claim:kraken-nft-marketplace:section:strategic_choices:3"]},"operating_model":{"body":"Kraken supplied custody, account funding, listings, bids, settlement, collection discovery and support. Users traded inside a centralized service, while creators and third-party contracts defined the underlying NFTs. The zero-gas promise depended on Kraken’s internal systems and did not mean blockchains stopped charging fees for withdrawals. Kraken has not disclosed marketplace take rate, creator payouts, active traders, custody cost, compliance cost, headcount or profit. After closure there is no operating marketplace model to evaluate—only the quality of the completed wind-down.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:operating_model:1","claim:kraken-nft-marketplace:section:operating_model:2","claim:kraken-nft-marketplace:section:operating_model:3"]},"token_and_value_capture":{"body":"Kraken did not launch a fungible token for the NFT marketplace in the reviewed sources. Potential value capture came from marketplace or account economics, customer retention and creator arrangements, but no marketplace fee or revenue total is published. NFT sellers could realize sale proceeds and creators could receive configured earnings; neither was a guaranteed return. The underlying collection token, any creator token and Kraken’s corporate value must be evaluated separately. After trading stopped, the only supported action was withdrawal rather than continued monetization.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:token_and_value_capture:1","claim:kraken-nft-marketplace:section:token_and_value_capture:2","claim:kraken-nft-marketplace:section:token_and_value_capture:3"]},"counterfactual":{"body":"A narrower non-custodial aggregator could have reduced custody and support costs while preserving Kraken account discovery, but it would lose the integrated zero-gas experience. A marketplace focused only on existing exchange clients or selected gaming assets might have reduced catalog complexity. A longer runway could help only if unmet demand existed. Kraken did not publish the tests needed to compare those alternatives, so the counterfactual cannot assume that better design would overcome a weak product priority or produce sustainable liquidity.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:counterfactual:1","claim:kraken-nft-marketplace:section:counterfactual:2","claim:kraken-nft-marketplace:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The terminal risk was access: customers had to move NFTs to self-custody before the deadline, and Kraken warned that anything left would no longer be accessible through the service. The record does not disclose how many users completed withdrawal, whether support disputes remain or how unwithdrawn assets were handled legally and operationally. Lifetime users, volume, unique buyers and sellers, take rate, creator payments, market share, losses and the destination of reallocated resources are also unknown. Those gaps prevent a precise financial postmortem.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:risks_and_unknowns:1","claim:kraken-nft-marketplace:section:risks_and_unknowns:2","claim:kraken-nft-marketplace:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Kraken NFT moved from a May 2022 waitlist to private beta, public beta in December 2022 and a broader public marketplace. Less than two years later the company announced withdrawal-only mode. Trading ended November 27, 2024 and the final shutdown occurred February 27, 2025. The lifecycle call is a failed product with an announced wind-down: it did not remain strategically important enough for Kraken to operate. That does not imply that every traded NFT failed or that Kraken itself ceased operating.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:lifecycle:1","claim:kraken-nft-marketplace:section:lifecycle:2","claim:kraken-nft-marketplace:section:lifecycle:3"]},"outlook_and_watch":{"body":"The marketplace has no recovery outlook because it is closed. Watch for post-closure customer claims, legal disclosures about inaccessible assets, a successor Kraken NFT feature or financial commentary explaining resource allocation. A future wallet gallery or third-party integration would be a new product and should not silently rewrite this marketplace’s lifecycle. The useful comparison is whether other exchange-owned NFT markets retained enough users and revenue to justify custody and support. Until Kraken publishes figures, this case supports only a strategic-exit conclusion, not a quantified loss estimate.","as_of":"2026-08-03","claim_ids":["claim:kraken-nft-marketplace:section:outlook_and_watch:1","claim:kraken-nft-marketplace:section:outlook_and_watch:2","claim:kraken-nft-marketplace:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:kraken-nft-marketplace:public-beta","type":"product_launch","date":"2022-12-22","date_precision":"day","description":"Kraken opened its NFT marketplace public beta.","claim_ids":["claim:kraken-nft-marketplace:event:public-beta"]},{"id":"event:kraken-nft-marketplace:withdrawal-only","type":"wind_down","date":"2024-11-27","date_precision":"day","description":"Kraken ended NFT listings, bids, purchases and sales.","claim_ids":["claim:kraken-nft-marketplace:event:withdrawal-only"]},{"id":"event:kraken-nft-marketplace:closure","type":"product_closure","date":"2025-02-27","date_precision":"day","description":"Kraken fully shut its NFT marketplace.","claim_ids":["claim:kraken-nft-marketplace:event:closure"]}],"sources":[{"id":"source:kraken-nft-marketplace:waitlist","title":"Kraken NFT is Coming: Join the Waitlist","url":"https://blog.kraken.com/product/nft/kraken-nft-is-coming-join-the-waitlist","publisher":"Kraken","published_at":"2022-05-03","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://blog.kraken.com/product/nft/kraken-nft-is-coming-join-the-waitlist","content_hash":null,"independence_group":"kraken","access_method":"direct_http","direct_http_status":200},{"id":"source:kraken-nft-marketplace:launch","title":"Kraken Opens NFT Marketplace Beta to the Public","url":"https://blog.kraken.com/product/nft/kraken-opens-nft-marketplace-beta-to-the-public","publisher":"Kraken","published_at":"2022-12-22","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://blog.kraken.com/product/nft/kraken-opens-nft-marketplace-beta-to-the-public","content_hash":null,"independence_group":"kraken","access_method":"direct_http","direct_http_status":200},{"id":"source:kraken-nft-marketplace:closure","title":"NFT marketplace closure: FAQ","url":"https://support.kraken.com/articles/nft-marketplace-closure-faq","publisher":"Kraken","published_at":"2025-03-31","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://support.kraken.com/articles/nft-marketplace-closure-faq","content_hash":null,"independence_group":"kraken","access_method":"direct_http","direct_http_status":200},{"id":"source:kraken-nft-marketplace:the-block","title":"Kraken to close NFT marketplace, shift focus to other projects","url":"https://www.theblock.co/post/328383/kraken-to-close-nft-marketplace-shift-focus-to-other-projects","publisher":"The Block","published_at":"2024-11-26","published_at_precision":"day","accessed_at":"2026-08-03T21:25:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T21:25:00Z","access_final_url":"https://www.theblock.co/post/328383/kraken-to-close-nft-marketplace-shift-focus-to-other-projects","content_hash":null,"independence_group":"the_block","access_method":"indexed_browser_snapshot","direct_http_status":403}],"claims":[{"id":"claim:kraken-nft-marketplace:status","field_path":"status.operating_state","assertion":"Kraken ended trading in November 2024 and fully shut the NFT marketplace on February 27, 2025.","value":"closed","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:closure","source:kraken-nft-marketplace:the-block"],"evidence_locator":"Operator closure FAQ and independent contemporaneous confirmation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:outcome","field_path":"outcome.label","assertion":"The marketplace failed as a continuing product and closed after an announced withdrawal period; underlying NFTs remained separate assets.","value":"failed_product_closed_orderly_wind_down","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:kraken-nft-marketplace:closure","source:kraken-nft-marketplace:the-block","source:kraken-nft-marketplace:launch"],"evidence_locator":"Launch proposition compared with terminal operator and independent closure records.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or holder-profitability claim.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Kraken NFT was a custodial, multi-chain marketplace inside Kraken accounts.","value":"Kraken NFT was a custodial, multi-chain marketplace inside Kraken accounts.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:waitlist","source:kraken-nft-marketplace:launch"],"evidence_locator":"Product and funding descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Kraken advertised zero network gas fees for marketplace trades.","value":"Kraken advertised zero network gas fees for marketplace trades.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:waitlist","source:kraken-nft-marketplace:launch"],"evidence_locator":"Launch feature list.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"Marketplace closure and underlying NFT existence are separate outcomes.","value":"Marketplace closure and underlying NFT existence are separate outcomes.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:kraken-nft-marketplace:closure"],"evidence_locator":"Self-custody withdrawal explanation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Public beta opened December 22, 2022 with more than 110 collections.","value":"Public beta opened December 22, 2022 with more than 110 collections.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:launch"],"evidence_locator":"Dated public-beta announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"Trading functions ended November 27, 2024.","value":"Trading functions ended November 27, 2024.","as_of":"2026-08-03","confidence":"high","kind":"fact"