,"support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"Adoption, competition, revenue and regulation were not ranked as closure causes by Kraken.","value":"Adoption, competition, revenue and regulation were not ranked as closure causes by Kraken.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:kraken-nft-marketplace:closure","source:kraken-nft-marketplace:the-block"],"evidence_locator":"Published rationale is narrower.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"The product used centralized custody and exchange funding rails.","value":"The product used centralized custody and exchange funding rails.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:waitlist","source:kraken-nft-marketplace:launch"],"evidence_locator":"Launch architecture.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"Kraken provided a staged trading stop and withdrawal window.","value":"Kraken provided a staged trading stop and withdrawal window.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:closure"],"evidence_locator":"Withdrawal-only and final deadline sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:strategic_choices:3","field_path":"analysis.sections.strategic_choi