wer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"Kraken imposed a February 27, 2025 final withdrawal deadline.","value":"Kraken imposed a February 27, 2025 final withdrawal deadline.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:closure"],"evidence_locator":"Closure FAQ.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"Kraken warned that unwithdrawn NFTs would no longer be accessible through the marketplace.","value":"Kraken warned that unwithdrawn NFTs would no longer be accessible through the marketplace.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:closure"],"evidence_locator":"Deadline consequence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"User, financial, withdrawal-completion and residual-claim data are not disclosed.","value":"User, financial, withdrawal-completion and residual-claim data are not disclosed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:kraken-nft-marketplace:closure","source:kraken-nft-marketplace:the-block"],"evidence_locator":"Terminal public record.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"The product progressed from waitlist to public beta during 2022.","value":"The product progressed from waitlist to public beta during 2022.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:waitlist","source:kraken-nft-marketplace:launch"],"evidence_locator":"Dated product announcements.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"Trading and final service ended on the published 2024 and 2025 dates.","value":"Trading and final service ended on the published 2024 and 2025 dates.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:closure","source:kraken-nft-marketplace:the-block"],"evidence_locator":"Terminal schedule.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Product failure is distinct from failure of Kraken or every supported collection.","value":"Product failure is distinct from failure of Kraken or every supported collection.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:kraken-nft-marketplace:closure"],"evidence_locator":"Closure scope is the NFT marketplace.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"Kraken NFT remains fully closed under the current operator record.","value":"Kraken NFT remains fully closed under the current operator record.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:closure"],"evidence_locator":"Final shutdown statement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"A future NFT feature would require separate identity and lifecycle analysis.","value":"A future NFT feature would require separate identity and lifecycle analysis.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:kraken-nft-marketplace:closure"],"evidence_locator":"Current product termination.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Post-closure claims and internal product economics remain unknown.","value":"Post-closure claims and internal product economics remain unknown.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:kraken-nft-marketplace:closure","source:kraken-nft-marketplace:the-block"],"evidence_locator":"Current public record.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:event:public-beta","field_path":"events[event:kraken-nft-marketplace:public-beta]","assertion":"Kraken opened its NFT marketplace public beta.","value":"2022-12-22","as_of":"2022-12-22","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:launch"],"evidence_locator":"Dated launch announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:event:withdrawal-only","field_path":"events[event:kraken-nft-marketplace:withdrawal-only]","assertion":"Kraken ended NFT listings, bids, purchases and sales.","value":"2024-11-27","as_of":"2024-11-27","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:closure","source:kraken-nft-marketplace:the-block"],"evidence_locator":"Operator and independent closure schedule.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kraken-nft-marketplace:event:closure","field_path":"events[event:kraken-nft-marketplace:closure]","assertion":"Kraken fully shut its NFT marketplace.","value":"2025-02-27","as_of":"2025-02-27","confidence":"high","kind":"fact","source_ids":["source:kraken-nft-marketplace:closure","source:kraken-nft-marketplace:the-block"],"evidence_locator":"Final operator deadline and independent confirmation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T21:25:00Z","next_review_at":"2026-08-10T21:25:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["lifetime_users","unique_buyers_and_sellers","volume","take_rate","creator_payments","market_share","operating_costs","withdrawal_completion","unwithdrawn_asset_disposition","reallocated_resource_destination"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Kraken NFT Marketplace, the Kraken exchange, Kraken Wallet, customers, creators and underlying NFT contracts are distinct products and owners.","metric_boundary":"Catalog size and supported currencies are product breadth, not users, volume, revenue, liquidity or product-market fit.","editorial_guardrail":"Use Kraken’s verified resource-reallocation rationale and label competing causal stories as hypotheses unless new internal evidence appears.","explicit_unknowns":["lifetime_users","unique_buyers_and_sellers","volume","take_rate","creator_payments","market_share","operating_costs","withdrawal_completion","unwithdrawn_asset_disposition","reallocated_resource_destination"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, adjacent-token economics and market price are kept separate.","No marketplace financial metric is published, so the profile does not manufacture a loss estimate from sector-level NFT volume."]}}');

INSERT INTO _nft_depth_wave_b_0096 (slug, canonical_profile) VALUES ('nodemonkes', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"ordinals_collection:nodemonkes","type":"ordinals_collection","slug":"nodemonkes","name":"NodeMonkes","aliases":[]},"classification":{"subtype":"Bitcoin Ordinals profile-picture collection","tags":["bitcoin","ordinals","pfp","fixed_supply","no_roadmap"],"chains":["Bitcoin"],"jurisdictions":[]},"status":{"operating_state":"operating_artifact_market_active_demand_unverified","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:status"]},"outcome":{"label":"middling_cultural_artifact_current_demand_unverified","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:nodemonkes:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"NodeMonkes is a fixed collection of 10,000 pixel-art characters stored as Bitcoin Ordinal inscriptions. Its official index exposes every item and its traits, while independent Ordinals explorers map the inscriptions to current owners and transfers. The project deliberately described itself as having no team, roadmap or execution promise after distribution. A NodeMonke is therefore a collectible Bitcoin artifact, not equity, a claim on protocol fees or a contract for future software and community benefits.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:what_it_is:1","claim:nodemonkes:section:what_it_is:2","claim:nodemonkes:section:what_it_is:3"]},"what_happened":{"body":"The creators inscribed the collection before its public sale, distributed 2,000 pieces through earlier activity and sold the remaining 8,000 in a December 21, 2023 Dutch auction. The official result records all 8,000 secured at a 0.03 BTC clearing price. Attention accelerated in early 2024, including a 17 BTC sale covered by CoinDesk. Later research documented a broad cooling in Ordinals collection volume after the first-half peak. The collection remains indexed, but a live index is not proof of current demand.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:what_happened:1","claim:nodemonkes:section:what_happened:2","claim:nodemonkes:section:what_happened:3"]},"why_this_outcome":{"body":"NodeMonkes gained attention by pairing a complete 10,000-piece cohort with Bitcoin-native storage, recognizable profile art and timing near the first major Ordinals market cycle. Its no-roadmap message made the artifact itself the product and removed dependence on promised games or software. That clarity reduced one kind of execution risk, but it also left few reasons for repeat use beyond collecting, identity and speculation. Independent peak-sale and later market evidence support cultural recognition, not durable liquidity or retained demand.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:why_this_outcome:1","claim:nodemonkes:section:why_this_outcome:2","claim:nodemonkes:section:why_this_outcome:3"]},"strategic_choices":{"body":"The creators chose early Bitcoin inscription provenance, a 10,000-piece profile collection and an onchain Dutch auction instead of an allowlist-heavy mint. They then rejected a conventional roadmap, named team and continuing execution obligation. That choice kept the promise narrow and made provenance, art and community the value proposition. The tradeoff is limited accountability and little disclosed product strategy. Collectors cannot evaluate a treasury, release schedule or operating milestones because the project says those are not part of the bargain.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:strategic_choices:1","claim:nodemonkes:section:strategic_choices:2","claim:nodemonkes:section:strategic_choices:3"]},"operating_model":{"body":"NodeMonkes does not present a conventional company or product operation. The enduring first-party surfaces are the inscriptions, the MonkeDEX trait index, auction records and community channels. Third-party Ordinals explorers and marketplaces provide custody views, listings and settlement. The creators do not publish staffing, entity ownership, treasury balances, royalties, marketplace fees, licensing income or ongoing expenses. The operating model is best understood as a finished artifact plus community and external market infrastructure, not a subscription or live-service business.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:operating_model:1","claim:nodemonkes:section:operating_model:2","claim:nodemonkes:section:operating_model:3"]},"token_and_value_capture":{"body":"The reviewed collection sources do not establish an official fungible token or a contractual token benefit for NodeMonke holders. Runes or similarly named assets can exist nearby without becoming collection entitlements. Holder value can come from selling an inscription, licensing or using its image, and community status, subject to actual rights and market demand. The 0.03 BTC auction proceeds went to the seller side of the launch; they were not a holder dividend. A later high sale benefited that transaction’s seller, not every owner.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:token_and_value_capture:1","claim:nodemonkes:section:token_and_value_capture:2","claim:nodemonkes:section:token_and_value_capture:3"]},"counterfactual":{"body":"A named team could have used auction proceeds to publish a treasury, develop tools and create repeat utility, but that would replace the project’s finished-artifact premise with execution risk. A token could add liquidity incentives while introducing emissions, allocation and regulatory questions unrelated to the inscriptions. A smaller supply might make ownership scarcer but reduce broad identity distribution. None of these alternatives was tested in the reviewed record, so they should be treated as design options rather than claims about a better financial outcome.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:counterfactual:1","claim:nodemonkes:section:counterfactual:2","claim:nodemonkes:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The main risks are thin Bitcoin NFT liquidity, marketplace fragmentation, custody mistakes, ordinal-indexing differences, anonymous or unclear operator accountability and dependence on cultural attention. A listed floor can disappear before execution and one headline sale can distort perceived depth. Current unique owners, holder concentration, active listings, executable bids, unique buyers and sellers, wash-adjusted volume, royalties, operator control, licensing terms and community retention are not disclosed in a stable, reproducible series. Those gaps keep the outcome at middling rather than proven success.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:risks_and_unknowns:1","claim:nodemonkes:section:risks_and_unknowns:2","claim:nodemonkes:section:risks_and_unknowns:3"]},"lifecycle":{"body":"NodeMonkes was inscribed and auctioned in late 2023, became a leading Ordinals profile collection during the early-2024 market surge and then entered a quieter period as sector volume declined. In August 2026 the full collection remains queryable through the official MonkeDEX and independent Ordinals infrastructure. The lifecycle call is a middling cultural artifact: it survived as an accessible collection and brand, but current owner retention and liquid demand are not proven. No roadmap failure is alleged because no roadmap was promised.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:lifecycle:1","claim:nodemonkes:section:lifecycle:2","claim:nodemonkes:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: NodeMonkes persists as a recognizable Bitcoin-native collectible without becoming an operating product company. Watch 30- and 90-day unique buyers and sellers, executable bids, holder concentration, transfer activity, marketplace support, official channel activity, licensing changes and any verified token or treasury announcement. Compare those signals with other early Ordinals cohorts rather than Ethereum profile collections alone. The call improves only if repeat independent demand is visible; it weakens if indexes, markets and community activity disappear together.","as_of":"2026-08-03","claim_ids":["claim:nodemonkes:section:outlook_and_watch:1","claim:nodemonkes:section:outlook_and_watch:2","claim:nodemonkes:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:nodemonkes:auction-mint-raise-2023-12-21","dimension":"mint_raise","label":"Computed 8,000-piece auction proceeds","value":240,"unit":"btc","currency":"BTC","window":{"start":"2023-12-21","end":"2023-12-21","definition":"final_dutch_auction_allocation"},"as_of":"2023-12-21","method":"Computed as 8,000 secured inscriptions multiplied by the official 0.03 BTC clearing price.","scope":{"collection":"NodeMonkes","allocation":"public_auction_8000"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:nodemonkes:metric:auction-mint-raise-2023-12-21"],"quality_flags":["computed_from_primary_source","gross_not_net","historical","not_holder_return"],"headline":false}],"events":[{"id":"event:nodemonkes:auction","type":"collection_sale","date":"2023-12-21","date_precision":"day","description":"The public Dutch auction secured all 8,000 offered NodeMonkes at 0.03 BTC each.","claim_ids":["claim:nodemonkes:event:auction"]},{"id":"event:nodemonkes:headline-sale","type":"secondary_sale","date":"2024-03-04","date_precision":"day","description":"CoinDesk reported a 17 BTC NodeMonke sale during the early Ordinals surge.","claim_ids":["claim:nodemonkes:event:headline-sale"]},{"id":"event:nodemonkes:current-index","type":"current_operation","date":"2026-08-03","date_precision":"day","description":"The official MonkeDEX continued to index all 10,000 inscriptions.","claim_ids":["claim:nodemonkes:event:current-index"]}],"sources":[{"id":"source:nodemonkes:monkedex","title":"MONKEDEX","url":"https://nodemonkes.com/monkedex","publisher":"NodeMonkes","published_at":